-- Uldum spawns, part 5 of 8: the rows of this part are deleted by key range before they are inserted, so the file can run twice.
-- Based on Legends of Azeroth 5.4.8 and The Cataclysm Preservation Project 4.3.4.

DELETE FROM `waypoint_data` WHERE (`id` > 91203590 OR (`id` = 91203590 AND `point` >= 7)) AND (`id` < 91221590 OR (`id` = 91221590 AND `point` <= 5));





